def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full-length marker determines the direction in which to extend
    # the object; place the new line just beyond the object, away from it.
    marker = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            marker = ("row", r, row[0])
            break
    if marker is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1:
                marker = ("col", c, grid[0][c])
                break
    if marker is None:
        return [row[:] for row in grid]
    axis, pos, marker_color = marker
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, marker_color)]
    if not obj:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    if axis == "row":
        r = max(r for r, c in obj)
        if r + 1 < h:
            out[r + 1] = [8] * w
    else:
        c = max(c for r, c in obj)
        if c + 1 < w:
            for r in range(h):
                out[r][c + 1] = 8
    return out

